import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) b[i] = nextLong();
        // keep / swp: min swaps so far when pair i is kept / swapped
        long inf = n + 1, keep = 0, swp = 1;
        for (int i = 1; i < n; i++) {
            long nk = inf, ns = inf;
            if (a[i] > a[i - 1] && b[i] > b[i - 1]) { nk = Math.min(nk, keep); ns = Math.min(ns, swp + 1); }
            if (a[i] > b[i - 1] && b[i] > a[i - 1]) { nk = Math.min(nk, swp); ns = Math.min(ns, keep + 1); }
            keep = nk;
            swp = ns;
        }
        long ans = Math.min(keep, swp);
        System.out.println(ans <= n ? ans : -1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}
	n := int(next())
	a := make([]int64, n)
	b := make([]int64, n)
	for i := range a {
		a[i] = next()
	}
	for i := range b {
		b[i] = next()
	}
	// keep / swp: min swaps so far when pair i is kept / swapped
	inf := int64(n + 1)
	keep, swp := int64(0), int64(1)
	for i := 1; i < n; i++ {
		nk, ns := inf, inf
		if a[i] > a[i-1] && b[i] > b[i-1] {
			nk = min(nk, keep)
			ns = min(ns, swp+1)
		}
		if a[i] > b[i-1] && b[i] > a[i-1] {
			nk = min(nk, swp)
			ns = min(ns, keep+1)
		}
		keep, swp = nk, ns
	}
	ans := min(keep, swp)
	if ans > int64(n) {
		ans = -1
	}
	fmt.Println(ans)
}
